const { chromium } = require('/tmp/claude-0/-root-design/f13cfb4d-b71e-4ed8-960a-ee0a8c2a8818/scratchpad/pwnode/node_modules/playwright-core');
const fs=require('fs');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1000,height:760},deviceScaleFactor:1});
 const logo=fs.readFileSync(process.cwd()+'/logo.svg').toString();
 const mark=fs.readFileSync(process.cwd()+'/mark.svg').toString();
 await page.setContent("'`<style>*{box-sizing:border-box}body{margin:0;background:#F6F2E9;color:#234D3C;font:12px Arial}main{padding:42px 50px}.full{display:flex;align-items:center;justify-content:center;height:360px}.full svg{width:800px;height:auto}.bottom{display:flex;align-items:center;justify-content:space-between;margin-top:50px;padding:30px 45px;border-top:1px solid #d8dbd0}.sample{display:flex;flex-direction:column;align-items:center;gap:20px}.dark{background:#234D3C;padding:25px}.dark path{fill:#F6F2E9}.label{color:#6a766b;font-size:10px;letter-spacing:1px}</style><main><div class="full">${logo}</div><div class="bottom"><div class="sample"><span style="display:block;width:96px;height:96px">${mark.replace('"'width=\"32\" height=\"32\"','width=\"96\" height=\"96\"')}</span><span class=\"label\">96 PX</span></div><div class=\"sample\">"'${mark}<span class="label">32 PX</span></div><div class="sample">${mark.replace('"'width=\"32\" height=\"32\"','width=\"16\" height=\"16\"')}<span class=\"label\">16 PX</span></div><div class=\"sample dark\">"'${mark.replace('"'width=\"32\" height=\"32\"','width=\"64\" height=\"64\"')}</div></div></main>"'`);
 await page.screenshot({path:'"'/tmp/fernway-proof-v2.png'});
 await browser.close();
})();
